-- Independent TaaS PostgreSQL schema. Safe to run repeatedly.
CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, username VARCHAR(120) UNIQUE NOT NULL, password_hash VARCHAR(128) NOT NULL, display_name VARCHAR(160) NOT NULL, email VARCHAR(255) DEFAULT '', role VARCHAR(40) NOT NULL DEFAULT 'customer', status VARCHAR(40) NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE users ADD COLUMN IF NOT EXISTS balance NUMERIC(16,4) NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS sessions (token VARCHAR(128) PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS permissions (code VARCHAR(120) PRIMARY KEY, name VARCHAR(160) NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions (role VARCHAR(40) NOT NULL, permission_code VARCHAR(120) NOT NULL REFERENCES permissions(code), PRIMARY KEY(role,permission_code));
CREATE TABLE IF NOT EXISTS user_permissions (user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, permission_code VARCHAR(120) NOT NULL REFERENCES permissions(code), allowed BOOLEAN NOT NULL, PRIMARY KEY(user_id,permission_code));
CREATE TABLE IF NOT EXISTS platform_settings (setting_key VARCHAR(120) PRIMARY KEY, setting_value TEXT NOT NULL DEFAULT '', updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS api_keys (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name VARCHAR(160) NOT NULL, token VARCHAR(160) UNIQUE NOT NULL, quota BIGINT NOT NULL DEFAULT 0, quota_used BIGINT NOT NULL DEFAULT 0, unlimited_quota BOOLEAN NOT NULL DEFAULT false, enabled BOOLEAN NOT NULL DEFAULT true, model_scope TEXT NOT NULL DEFAULT '', expires_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS packages (id BIGSERIAL PRIMARY KEY, name VARCHAR(160) NOT NULL, price NUMERIC(12,2) NOT NULL, quota BIGINT NOT NULL, valid_days INTEGER NOT NULL, enabled BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS channels (id BIGSERIAL PRIMARY KEY, name VARCHAR(160) NOT NULL, base_url TEXT NOT NULL, api_key TEXT NOT NULL, model_scope TEXT NOT NULL DEFAULT '', enabled BOOLEAN NOT NULL DEFAULT true, weight INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS model_prices (model VARCHAR(160) PRIMARY KEY, input_price NUMERIC(16,6) NOT NULL CHECK(input_price>=0), output_price NUMERIC(16,6) NOT NULL CHECK(output_price>=0));
CREATE TABLE IF NOT EXISTS usage_logs (id BIGSERIAL PRIMARY KEY, user_id BIGINT REFERENCES users(id) ON DELETE SET NULL, api_key_id BIGINT REFERENCES api_keys(id) ON DELETE SET NULL, channel_id BIGINT REFERENCES channels(id) ON DELETE SET NULL, model VARCHAR(160) NOT NULL, tokens_in INTEGER NOT NULL DEFAULT 0, tokens_out INTEGER NOT NULL DEFAULT 0, cost NUMERIC(16,8) NOT NULL DEFAULT 0, status_code INTEGER NOT NULL DEFAULT 200, latency_ms INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_taas_usage_created ON usage_logs(created_at DESC);
CREATE TABLE IF NOT EXISTS payment_orders (id BIGSERIAL PRIMARY KEY, order_no VARCHAR(80) UNIQUE NOT NULL, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, package_id BIGINT REFERENCES packages(id) ON DELETE SET NULL, amount NUMERIC(16,4) NOT NULL, quota BIGINT NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL DEFAULT 'pending', channel VARCHAR(40) NOT NULL DEFAULT 'manual', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), paid_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS recharge_transactions (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, amount NUMERIC(16,4) NOT NULL, balance_before NUMERIC(16,4) NOT NULL, balance_after NUMERIC(16,4) NOT NULL, kind VARCHAR(40) NOT NULL, reference VARCHAR(160) NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE recharge_transactions ADD COLUMN IF NOT EXISTS channel VARCHAR(40) NOT NULL DEFAULT '';
ALTER TABLE recharge_transactions ADD COLUMN IF NOT EXISTS payment_trade_no VARCHAR(160) NOT NULL DEFAULT '';
ALTER TABLE recharge_transactions ADD COLUMN IF NOT EXISTS operator_id BIGINT REFERENCES users(id) ON DELETE SET NULL;
CREATE TABLE IF NOT EXISTS redemption_codes (id BIGSERIAL PRIMARY KEY, code VARCHAR(80) UNIQUE NOT NULL, amount NUMERIC(16,4) NOT NULL DEFAULT 0, quota BIGINT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'active', used_by BIGINT REFERENCES users(id) ON DELETE SET NULL, used_at TIMESTAMPTZ);
ALTER TABLE packages ADD COLUMN IF NOT EXISTS model_routes JSONB NOT NULL DEFAULT '{}';
ALTER TABLE payment_orders ADD COLUMN IF NOT EXISTS entitlement BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE payment_orders ADD COLUMN IF NOT EXISTS valid_days INTEGER NOT NULL DEFAULT 30;
ALTER TABLE payment_orders ADD COLUMN IF NOT EXISTS model_routes JSONB NOT NULL DEFAULT '{}';
ALTER TABLE payment_orders ADD COLUMN IF NOT EXISTS quota_used BIGINT NOT NULL DEFAULT 0;
ALTER TABLE payment_orders ADD COLUMN IF NOT EXISTS expires_at TIMESTAMPTZ;
ALTER TABLE api_keys ADD COLUMN IF NOT EXISTS consumption_order_id BIGINT REFERENCES payment_orders(id) ON DELETE SET NULL;
ALTER TABLE usage_logs ADD COLUMN IF NOT EXISTS order_id BIGINT REFERENCES payment_orders(id) ON DELETE SET NULL;
ALTER TABLE usage_logs ADD COLUMN IF NOT EXISTS task_type TEXT NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS usage_reservations (id TEXT PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES payment_orders(id) ON DELETE CASCADE, api_key_id BIGINT NOT NULL REFERENCES api_keys(id) ON DELETE CASCADE, tokens BIGINT NOT NULL, expires_at TIMESTAMPTZ NOT NULL);
